void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::String> name_str = name->ToString(isolate->GetCurrentContext()).ToLocalChecked();
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  String name_value = ToCoreString(name_str);
  Element* element = frame->GetDocument()->getElementById(name_value);
  if (element) {
    info.GetReturnValue().Set(ToV8(element, isolate));
    return;
  }

  Node* node = frame->GetDocument()->GetNamedItem(name_value);
  if (node) {
    info.GetReturnValue().Set(ToV8(node, isolate));
    return;
  }

  HTMLCollection* collection = frame->GetDocument()->GetElementsByName(name_value);
  if (collection && collection->length() > 0) {
    info.GetReturnValue().Set(ToV8(collection, isolate));
    return;
  }

  // No matching item found
  return;
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Value> result;

  if (!name->IsString()) {
    return;
  }

  v8::Local<v8::String> nameStr = name->ToString(isolate->GetCurrentContext()).ToLocalChecked();
  v8::Local<v8::Object> holder = info.Holder();

  LocalDOMWindow* window = LocalDOMWindow::From(v8::Utils::OpenHandle(*holder));
  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame || !frame->GetDocument()) {
    return;
  }

  const NamedNodeMap* namedItems = frame->GetDocument()->GetElementsByName();
  if (namedItems) {
    for (size_t i = 0; i < namedItems->length(); ++i) {
      Node* node = namedItems->item(i);
      if (nameStr->Equals(isolate->GetCurrentContext(), v8::String::NewFromUtf8(isolate, node->localName().utf8().c_str(), v8::NewStringType::kNormal).ToLocalChecked()).FromMaybe(false)) {
        result = node->ToV8Object(isolate);
        break;
      }
    }
  }

  if (!result.IsEmpty()) {
    info.GetReturnValue().Set(result);
  }
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  v8::String::Value name_value(isolate, name);
  if (!name_value.ToCString()) {
    return;
  }

  String identifier = String::FromUTF8(*name_value.ToCString());
  if (identifier.IsNull()) {
    return;
  }

  Document* document = frame->GetDocument();
  if (!document) {
    return;
  }

  Element* element = document->GetElementById(identifier);
  if (element) {
    info.GetReturnValue().Set(ToV8(element, info.GetIsolate(), info.GetHolder()));
    return;
  }

  Node* node = document->GetNodeById(identifier);
  if (node) {
    info.GetReturnValue().Set(ToV8(node, info.GetIsolate(), info.GetHolder()));
    return;
  }

  HTMLCollection* collection = document->GetElementsByTagName(identifier);
  if (collection && collection->length() > 0) {
    info.GetReturnValue().Set(ToV8(collection, info.GetIsolate(), info.GetHolder()));
    return;
  }

  info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Object> holder = info.Holder();

  // Retrieve the associated LocalDOMWindow
  LocalDOMWindow* window = ToLocalDOMWindow(holder);
  if (!window)
    return;

  // Check if the window is attached to a frame
  Frame* frame = window->GetFrame();
  if (!frame)
    return;

  // Convert the v8::Name to a string
  v8::String::Value name_str(isolate, name);
  if (!name_str)
    return;

  String name_string(*name_str);

  // Search for sub-frames and named items in the document
  Element* element = frame->document()->getElementById(name_string);
  if (element) {
    info.GetReturnValue().Set(toV8(element, holder, isolate));
    return;
  }

  // Check for sub-frames
  Frame* sub_frame = frame->Tree().Find(name_string);
  if (sub_frame && sub_frame->IsAttached()) {
    info.GetReturnValue().Set(toV8(sub_frame->DomWindow(), holder, isolate));
    return;
  }

  // Default case or no match found
  info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
    v8::Isolate* isolate = info.GetIsolate();
    v8::Local<v8::Object> holder = info.Holder();

    LocalDOMWindow* window = ToLocalDOMWindow(holder);
    if (!window || !window->IsAttachedToFrame())
        return;

    Frame* frame = window->GetFrame();
    if (!frame || !frame->GetDocument())
        return;

    String name_str = v8_string_to_string(name);
    Element* element = frame->GetDocument()->GetElementById(name_str);
    if (!element)
        return;

    v8::Local<v8::Value> value;
    element->Wrap(isolate, &value);
    info.GetReturnValue().Set(value);
}
